import{_ as t,o as a,c as e,a5 as n}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"Android uni-app 生产包需要什么？签名 SHA1、keystore 与构建流程","description":"从签名 SHA1、keystore 到 DCloud AppKey 与第三方 SDK，梳理 uni-app Android 生产包四层要素与完整构建流程。","frontmatter":{"title":"Android uni-app 生产包需要什么？签名 SHA1、keystore 与构建流程","date":"2026-05-19T00:00:00.000Z","tags":["uni-app","DCloud","离线打包","Android","AppKey","keystore","SHA1","Gradle"],"categories":["移动开发"],"description":"从签名 SHA1、keystore 到 DCloud AppKey 与第三方 SDK，梳理 uni-app Android 生产包四层要素与完整构建流程。"},"headers":[],"relativePath":"posts/移动开发/uni-app/Android uni-app 生产包需要什么？签名 SHA1、keystore 与构建流程.md","filePath":"posts/移动开发/uni-app/Android uni-app 生产包需要什么？签名 SHA1、keystore 与构建流程.md","lastUpdated":1790163617000}'),d={name:"posts/移动开发/uni-app/Android uni-app 生产包需要什么？签名 SHA1、keystore 与构建流程.md"};function i(p,s,o,r,l,h){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="android-uni-app-生产包需要什么" tabindex="-1">Android uni-app 生产包需要什么？ <a class="header-anchor" href="#android-uni-app-生产包需要什么" aria-label="Permalink to &quot;Android uni-app 生产包需要什么？&quot;">​</a></h1><p>本文是 <a href="/blog/posts/移动开发/uni-app/DCloud AppKey 是什么？离线打包三要素必须一致">DCloud AppKey 是什么？</a> 的续篇。完整三平台流程见 <a href="/blog/posts/移动开发/uni-app/移动端打包签名与 DCloud 离线打包教程">移动端打包签名与 DCloud 离线打包教程</a>。</p><h2 id="签名-sha1-是什么" tabindex="-1">签名 SHA1 是什么？ <a class="header-anchor" href="#签名-sha1-是什么" aria-label="Permalink to &quot;签名 SHA1 是什么？&quot;">​</a></h2><p>Android 每个 APK 安装前都要用 <strong>签名证书</strong> 做数字签名，证明「这个包是谁发的、有没有被改过」。</p><p><strong>SHA1</strong> 就是这张签名证书的 <strong>指纹</strong>（一串 40 位十六进制，例如 <code>AA:BB:CC:...</code>）：</p><ul><li>同一张 keystore → SHA1 <strong>永远一样</strong></li><li>换 keystore 或换 key → SHA1 <strong>会变</strong></li><li>任何人解包 APK 都能读到，<strong>不是秘密</strong></li></ul><p>可以类比：</p><table tabindex="0"><thead><tr><th>概念</th><th>类比</th></tr></thead><tbody><tr><td>keystore（<code>.keystore</code> / <code>.jks</code>）</td><td>公章本体</td></tr><tr><td>keyAlias</td><td>章上的名字</td></tr><tr><td>storePassword / keyPassword</td><td>开保险柜、盖章的密码</td></tr><tr><td>SHA1</td><td>公章在备案系统里的指纹编号</td></tr></tbody></table><p>Google Play、微信开放平台、DCloud 后台登记时，常要求填 SHA1，就是为了确认「以后上架 / 调 SDK 的 APK，必须是这张证书签的」。</p><blockquote><p><strong>延伸阅读：</strong> SHA1 指纹和安装验签用的「内容 hash」不是一回事；Android / iOS / 鸿蒙谁发证也不同，详见 <a href="/blog/posts/移动开发/uni-app/SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同">SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同</a>。</p></blockquote><h2 id="android-生产包需要什么-按层次" tabindex="-1">Android 生产包需要什么？（按层次） <a class="header-anchor" href="#android-生产包需要什么-按层次" aria-label="Permalink to &quot;Android 生产包需要什么？（按层次）&quot;">​</a></h2><p>你们项目是 <strong>uni 业务 + DCloud 原生壳 + 多个 SDK</strong>，生产包大致分四层：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph L1[&quot;① 身份与版本&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A1[包名 applicationId]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A2[versionCode / versionName]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph L2[&quot;② APK 签名&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B1[keystore 文件]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B2[alias + 密码]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B3[SHA1 指纹]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph L3[&quot;③ DCloud 离线授权&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C1[appid]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C2[DCloud AppKey]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C3[www 资源包]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph L4[&quot;④ 第三方 SDK&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        D1[个推/UniPush]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        D2[华为推送等]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L1 --&gt; APK</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L2 --&gt; APK</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L3 --&gt; APK</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L4 --&gt; APK</span></span></code></pre></div><h3 id="_1-应用身份与版本-上架、更新用" tabindex="-1">① 应用身份与版本（上架、更新用） <a class="header-anchor" href="#_1-应用身份与版本-上架、更新用" aria-label="Permalink to &quot;① 应用身份与版本（上架、更新用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>东西</th><th>你们项目在哪</th><th>作用</th></tr></thead><tbody><tr><td><strong>包名</strong> <code>applicationId</code></td><td><code>build.gradle</code> → <code>com.future.hyqhjskh</code></td><td>App 唯一 ID；换包名 = 另一个 App</td></tr><tr><td><strong>versionCode</strong></td><td><code>build.gradle</code> → <code>155</code></td><td>整数，系统 / App Store 比「谁更新」</td></tr><tr><td><strong>versionName</strong></td><td><code>build.gradle</code> → <code>&quot;1.5.5&quot;</code></td><td>给用户看的版本号</td></tr><tr><td><strong>App 名称、图标</strong></td><td><code>prepare-build</code> 从品牌资源同步</td><td>桌面显示名、启动图标</td></tr></tbody></table><h3 id="_2-apk-签名-google-各平台认「是不是你发的」" tabindex="-1">② APK 签名（Google / 各平台认「是不是你发的」） <a class="header-anchor" href="#_2-apk-签名-google-各平台认「是不是你发的」" aria-label="Permalink to &quot;② APK 签名（Google / 各平台认「是不是你发的」）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>东西</th><th>你们项目在哪</th><th>作用</th></tr></thead><tbody><tr><td><strong>keystore 文件</strong></td><td><code>.secrets/android/keystore/*.keystore</code></td><td>签名私钥容器</td></tr><tr><td><strong>RELEASE_KEY_ALIAS</strong></td><td><code>secrets.properties</code></td><td>keystore 里用哪把 key</td></tr><tr><td><strong>RELEASE_STORE_PASSWORD</strong></td><td><code>secrets.properties</code></td><td>打开 keystore</td></tr><tr><td><strong>RELEASE_KEY_PASSWORD</strong></td><td><code>secrets.properties</code></td><td>使用 key 签名</td></tr><tr><td><strong>SHA1 / SHA256</strong></td><td>从 keystore 或 APK <strong>算出来</strong>，填到各后台</td><td>指纹，不写在工程里</td></tr></tbody></table><p>Gradle 里用法：</p><div class="language-gradle vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gradle</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>signingConfigs {</span></span>
<span class="line"><span>    config {</span></span>
<span class="line"><span>        keyAlias releaseKeyAlias</span></span>
<span class="line"><span>        keyPassword releaseKeyPassword</span></span>
<span class="line"><span>        storeFile file(releaseStoreFileName)</span></span>
<span class="line"><span>        storePassword releaseStorePassword</span></span>
<span class="line"><span>        v1SigningEnabled true</span></span>
<span class="line"><span>        v2SigningEnabled true</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Release 构建会强制用这套签名；<strong>丢 keystore ≈ 无法以同一 App 身份更新</strong>（只能换包名重新上架）。</p><p><strong>查 SHA1 示例</strong>（把路径换成你们的 keystore）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">keytool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keystore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .secrets/android/keystore/xxx.keystore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -alias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> __UNI__3EAF30F</span></span></code></pre></div><p>或对已打好的 APK：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 解压 APK，对 META-INF/CERT.RSA</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">keytool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -printcert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CERT.RSA</span></span></code></pre></div><h3 id="_3-dcloud-离线打包-uni-能不能跑" tabindex="-1">③ DCloud 离线打包（uni 能不能跑） <a class="header-anchor" href="#_3-dcloud-离线打包-uni-能不能跑" aria-label="Permalink to &quot;③ DCloud 离线打包（uni 能不能跑）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>东西</th><th>在哪</th><th>作用</th></tr></thead><tbody><tr><td><strong>appid</strong></td><td><code>dcloud_control.xml</code> → <code>__UNI__3EAF30F</code></td><td>加载哪个 uni 应用</td></tr><tr><td><strong>DCloud AppKey</strong></td><td><code>AndroidManifest</code> + <code>secrets.properties</code></td><td>DCloud 离线授权凭证</td></tr><tr><td><strong>登记时的 SHA1</strong></td><td>dev.dcloud.net.cn 后台</td><td>和 AppKey <strong>绑定</strong>；APK 实际签名 SHA1 必须一致</td></tr><tr><td><strong>www 资源</strong></td><td><code>assets/apps/__UNI__3EAF30F/www/</code></td><td>编译好的 uni 页面 / 逻辑</td></tr></tbody></table><p>DCloud 校验的是 <strong>四条一起</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>appid + 包名 + APK 签名 SHA1 + AppKey</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>   必须和后台申请 AppKey 时填的一致</span></span></code></pre></div><p>所以：<strong>AppKey 管 DCloud 认不认你；SHA1 管「是不是当初登记那张证书签的包」</strong>——两件事相关但不相同。</p><h3 id="_4-第三方-sdk-推送、登录等-按品牌可选" tabindex="-1">④ 第三方 SDK（推送、登录等，按品牌可选） <a class="header-anchor" href="#_4-第三方-sdk-推送、登录等-按品牌可选" aria-label="Permalink to &quot;④ 第三方 SDK（推送、登录等，按品牌可选）&quot;">​</a></h3><p>来自 <code>secrets.properties</code>，<code>prepare-build</code> 按品牌写入：</p><table tabindex="0"><thead><tr><th>键名</th><th>作用</th></tr></thead><tbody><tr><td><code>GETUI_APPID</code> / <code>GY_APP_ID</code></td><td>个推 / 一键登录</td></tr><tr><td><code>UNIPUSH_APPKEY</code> / <code>UNIPUSH_APPSECRET</code></td><td>UniPush 2.0</td></tr><tr><td><code>GT_INSTALL_CHANNEL</code></td><td>个推安装渠道统计</td></tr><tr><td><code>HUAWEI_APP_ID</code></td><td>华为厂商推送（hyqh 等品牌）</td></tr><tr><td><code>agconnect-services.json</code></td><td>华为 AGC 配置（slzq / hyqh 等）</td></tr></tbody></table><p>这些 <strong>不参与 DCloud AppKey 校验</strong>，但生产包若要用推送 / 一键登录，缺了会功能异常。</p><h2 id="生产包完整流程-和你们仓库对应" tabindex="-1">生产包完整流程（和你们仓库对应） <a class="header-anchor" href="#生产包完整流程-和你们仓库对应" aria-label="Permalink to &quot;生产包完整流程（和你们仓库对应）&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. prepare-build --apply          → 品牌、包名、AppKey、图标、SDK 配置</span></span>
<span class="line"><span>2. HBuilderX 发行 → 生成 www      → uni 业务编译产物</span></span>
<span class="line"><span>3. sync-uni-www-to-simpleDemo.sh  → www 拷进 assets</span></span>
<span class="line"><span>4. ./gradlew :simpleDemo:assembleRelease</span></span>
<span class="line"><span>   ├── 读 secrets.properties（keystore、AppKey、推送 key）</span></span>
<span class="line"><span>   ├── Gradle 检查：Release 时 AppKey、keystore 密码非空</span></span>
<span class="line"><span>   ├── 用 keystore 签名 → 产出 hyqh-jskh-prod.apk</span></span>
<span class="line"><span>   └── APK 自带一个 SHA1</span></span>
<span class="line"><span>5. （可选）渠道包 VasDolly / channel.txt</span></span>
<span class="line"><span>6. 上传应用商店 / 内部分发</span></span></code></pre></div><h2 id="几样东西容易混-对照一下" tabindex="-1">几样东西容易混，对照一下 <a class="header-anchor" href="#几样东西容易混-对照一下" aria-label="Permalink to &quot;几样东西容易混，对照一下&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>谁发的</th><th>防什么</th><th>存在哪</th></tr></thead><tbody><tr><td><strong>keystore + 密码</strong></td><td>你们自己</td><td>APK 被篡改、冒名更新</td><td><code>.secrets/android/keystore/</code></td></tr><tr><td><strong>SHA1</strong></td><td>从 keystore <strong>算出来</strong></td><td>各平台核对「是不是这张证签的」</td><td>填 DCloud / 微信 / Google 等后台</td></tr><tr><td><strong>DCloud AppKey</strong></td><td>DCloud 后台生成</td><td>未授权跑 uni 离线包</td><td><code>secrets.properties</code> + Manifest</td></tr><tr><td><strong>个推 / 华为等 Key</strong></td><td>各 SDK 厂商</td><td>推送、登录等能力</td><td><code>secrets.properties</code></td></tr></tbody></table><h2 id="一句话记" tabindex="-1">一句话记 <a class="header-anchor" href="#一句话记" aria-label="Permalink to &quot;一句话记&quot;">​</a></h2><ul><li><strong>SHA1</strong> = 签名证书的指纹，证明「这个 APK 是哪张证签的」</li><li><strong>keystore</strong> = 签名用的私钥文件，生产包必备</li><li><strong>AppKey</strong> = DCloud 发的 uni 离线许可证，且和 <strong>登记时的 SHA1</strong> 绑在一起</li><li><strong>www</strong> = uni 业务本身</li><li><strong>推送等 Key</strong> = 原生能力插件的配置</li></ul><p>生产包最少要保证：<strong>keystore 能签、SHA1 和 DCloud 后台一致、AppKey 对、www 是最新的</strong>。</p><hr><p><strong>延伸阅读：</strong></p><ul><li><a href="/blog/posts/移动开发/uni-app/移动端打包签名与 DCloud 离线打包教程">移动端打包签名与 DCloud 离线打包教程（系列总览）</a></li><li><a href="/blog/posts/移动开发/uni-app/Android keystore 密码与 APK 签名：打包时发生什么、安装时验什么">Android keystore 密码与 APK 签名：打包时发生什么、安装时验什么</a> — keystore 两个密码、空密码风险、验签双 hash 对比</li><li><a href="/blog/posts/移动开发/uni-app/SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同">SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同</a> — 证书指纹 vs 内容 hash、三平台发证对比</li></ul><p>下一步可写一份「<strong>从 keystore 查 SHA1 → 和 DCloud 后台逐项对照</strong>」的检查清单，照着打勾即可。</p>`,44)])])}const k=t(d,[["render",i]]);export{g as __pageData,k as default};
